import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.DbSlGjul.js";const g=JSON.parse('{"title":"How to perform each task","description":"Starting states, actions, success criteria, timeouts, and reset instructions for all 13 HiveBoard evaluation conditions.","frontmatter":{"title":"How to perform each task","description":"Starting states, actions, success criteria, timeouts, and reset instructions for all 13 HiveBoard evaluation conditions."},"headers":[],"relativePath":"benchmark/tasks.md","filePath":"benchmark/tasks.md","lastUpdated":1789045003000}'),o={name:"benchmark/tasks.md"};function n(i,t,s,h,l,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-perform-each-task" tabindex="-1">How to perform each task <a class="header-anchor" href="#how-to-perform-each-task" aria-label="Permalink to &quot;How to perform each task&quot;">​</a></h1><p>Select a task below for its starting state, required actions, success criterion, and reset. Record <strong>five trials for each of the 13 conditions (65 trials total)</strong>. The two ball-valve configurations are separate conditions.</p><table tabindex="0"><thead><tr><th>Task</th><th>What to do</th><th style="text-align:right;">Timeout</th></tr></thead><tbody><tr><td><a href="#ball-valve">Ball valve</a></td><td>Rotate the handle 90° from closed to open</td><td style="text-align:right;">60 s</td></tr><tr><td><a href="#ball-valve-with-friction-ring">Ball valve with friction ring</a></td><td>Perform the same rotation with the ring fitted</td><td style="text-align:right;">90 s</td></tr><tr><td><a href="#small-gate-valve">Small gate valve</a></td><td>Rotate the stem one full turn from closed</td><td style="text-align:right;">90 s</td></tr><tr><td><a href="#large-gate-valve">Large gate valve</a></td><td>Rotate the stem one full turn from closed</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#circuit-breaker">Circuit breaker</a></td><td>Move the toggle to the opposite state and hold it</td><td style="text-align:right;">60 s</td></tr><tr><td><a href="#light-bulb-and-socket">Light bulb and socket</a></td><td>Thread the bulb into the socket until seated</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#m8-threaded-fastener">M8 threaded fastener</a></td><td>Thread the bolt along the available length</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#m30-threaded-fastener">M30 threaded fastener</a></td><td>Thread the bolt along the available length</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#threaded-peg-insertion">Threaded peg insertion</a></td><td>Align and thread the free peg into the socket until seated</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#covered-button">Covered button</a></td><td>Open the cover, then press the button until actuation</td><td style="text-align:right;">60 s</td></tr><tr><td><a href="#lock-and-key">Lock and key</a></td><td>Grasp the key, insert it vertically, and rotate to unlock</td><td style="text-align:right;">180 s</td></tr><tr><td><a href="#sliding-drawer">Sliding drawer</a></td><td>Grasp the handle, pull open, then push closed</td><td style="text-align:right;">120 s</td></tr><tr><td><a href="#shock-absorber">Shock absorber</a></td><td>Grasp the pin, align it with the hole, and insert it fully</td><td style="text-align:right;">180 s</td></tr></tbody></table><h2 id="before-every-trial" tabindex="-1">Before every trial <a class="header-anchor" href="#before-every-trial" aria-label="Permalink to &quot;Before every trial&quot;">​</a></h2><p>Fully seat the attachment and restore the starting state described below. For loose parts, document their starting pose and use the same pose between trials. Where initial thread engagement is part of the setup, document and restore that engagement; this guide does not introduce a new number of starting turns.</p><p>Start the end-effector from the same neutral pose for the platform. Record the complete physical trial with an external camera. Start timing with the first commanded task motion; when using the <a href="/hivedocs/benchmark/evaluation-runner">Evaluation Runner</a>, begin that motion when the countdown reaches zero. Stop at success, a safety stop, or the timeout.</p><p>For familiarization, outcome labels, and handling broken or displaced parts, follow the <a href="/hivedocs/benchmark/protocol">evaluation protocol</a>. Example videos remain available in the runner.</p><h2 id="ball-valve" tabindex="-1">Ball valve <a class="header-anchor" href="#ball-valve" aria-label="Permalink to &quot;Ball valve&quot;">​</a></h2><p>Task ID: <code>valve_ball</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Handle closed; no friction ring fitted; attachment fully seated.</td></tr><tr><td>Action</td><td>Engage the handle and rotate it 90° toward the open position.</td></tr><tr><td>Success</td><td>The handle reaches the open position after a 90° rotation.</td></tr><tr><td>Timeout</td><td>60 s.</td></tr><tr><td>Reset</td><td>Return the handle to closed and check attachment seating.</td></tr></tbody></table><h2 id="ball-valve-with-friction-ring" tabindex="-1">Ball valve with friction ring <a class="header-anchor" href="#ball-valve-with-friction-ring" aria-label="Permalink to &quot;Ball valve with friction ring&quot;">​</a></h2><p>Task ID: <code>valve_ball_ring</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Friction ring fitted; handle closed; attachment fully seated. Document which ring is used.</td></tr><tr><td>Action</td><td>Engage the handle and rotate it 90° toward the open position with the ring fitted.</td></tr><tr><td>Success</td><td>The handle reaches the open position after a 90° rotation.</td></tr><tr><td>Timeout</td><td>90 s.</td></tr><tr><td>Reset</td><td>Keep the same ring fitted, return the handle to closed, and check attachment seating.</td></tr></tbody></table><h2 id="small-gate-valve" tabindex="-1">Small gate valve <a class="header-anchor" href="#small-gate-valve" aria-label="Permalink to &quot;Small gate valve&quot;">​</a></h2><p>Task ID: <code>valve_gate_small</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Stem in the closed starting position. Identify its initial orientation so one full turn can be observed.</td></tr><tr><td>Action</td><td>Turn the valve to rotate the stem through one complete revolution from closed.</td></tr><tr><td>Success</td><td>The stem completes one full turn (360°). Full opening travel is not required.</td></tr><tr><td>Timeout</td><td>90 s.</td></tr><tr><td>Reset</td><td>Reverse the motion to restore the closed starting position and initial orientation. Keep the board position unchanged.</td></tr></tbody></table><h2 id="large-gate-valve" tabindex="-1">Large gate valve <a class="header-anchor" href="#large-gate-valve" aria-label="Permalink to &quot;Large gate valve&quot;">​</a></h2><p>Task ID: <code>valve_gate_large</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Stem in the closed starting position. Identify its initial orientation so one full turn can be observed.</td></tr><tr><td>Action</td><td>Turn the valve to rotate the stem through one complete revolution from closed.</td></tr><tr><td>Success</td><td>The stem completes one full turn (360°). Full opening travel is not required.</td></tr><tr><td>Timeout</td><td>120 s.</td></tr><tr><td>Reset</td><td>Reverse the motion to restore the closed starting position and initial orientation. Keep the board position unchanged.</td></tr></tbody></table><h2 id="circuit-breaker" tabindex="-1">Circuit breaker <a class="header-anchor" href="#circuit-breaker" aria-label="Permalink to &quot;Circuit breaker&quot;">​</a></h2><p>Task ID: <code>circuit_breaker</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Toggle in the documented initial state.</td></tr><tr><td>Action</td><td>Move the toggle to the opposite state and hold it there.</td></tr><tr><td>Success</td><td>The toggle has changed state and is held in that state.</td></tr><tr><td>Timeout</td><td>60 s.</td></tr><tr><td>Reset</td><td>Return the toggle to the initial state and check that it moves freely.</td></tr></tbody></table><h2 id="light-bulb-and-socket" tabindex="-1">Light bulb and socket <a class="header-anchor" href="#light-bulb-and-socket" aria-label="Permalink to &quot;Light bulb and socket&quot;">​</a></h2><p>Task ID: <code>light_bulb</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Bulb removed from the socket and placed in its documented starting pose; thread clear.</td></tr><tr><td>Action</td><td>Align the bulb with the socket and rotate it to engage and advance the thread.</td></tr><tr><td>Success</td><td>The bulb is fully threaded until seated.</td></tr><tr><td>Timeout</td><td>120 s.</td></tr><tr><td>Reset</td><td>Unscrew and remove the bulb, restore its starting pose, and inspect the thread.</td></tr></tbody></table><h2 id="m8-threaded-fastener" tabindex="-1">M8 threaded fastener <a class="header-anchor" href="#m8-threaded-fastener" aria-label="Permalink to &quot;M8 threaded fastener&quot;">​</a></h2><p>Task ID: <code>thread_m8</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Bolt at the documented initial thread engagement; thread clear.</td></tr><tr><td>Action</td><td>Rotate the bolt to advance it along the thread.</td></tr><tr><td>Success</td><td>The bolt is fully threaded along the available length.</td></tr><tr><td>Timeout</td><td>120 s.</td></tr><tr><td>Reset</td><td>Return the bolt to its initial engagement and inspect the thread.</td></tr></tbody></table><h2 id="m30-threaded-fastener" tabindex="-1">M30 threaded fastener <a class="header-anchor" href="#m30-threaded-fastener" aria-label="Permalink to &quot;M30 threaded fastener&quot;">​</a></h2><p>Task ID: <code>thread_m30</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Bolt at the documented initial thread engagement; thread clear.</td></tr><tr><td>Action</td><td>Rotate the bolt to advance it along the thread.</td></tr><tr><td>Success</td><td>The bolt is fully threaded along the available length.</td></tr><tr><td>Timeout</td><td>120 s.</td></tr><tr><td>Reset</td><td>Return the bolt to its initial engagement and inspect the thread.</td></tr></tbody></table><h2 id="threaded-peg-insertion" tabindex="-1">Threaded peg insertion <a class="header-anchor" href="#threaded-peg-insertion" aria-label="Permalink to &quot;Threaded peg insertion&quot;">​</a></h2><p>Task ID: <code>peg_insertion</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Socket empty; free 8 mm threaded peg in its documented pose next to the socket.</td></tr><tr><td>Action</td><td>Pick up the peg, align it with the socket, and rotate it to engage and advance the thread.</td></tr><tr><td>Success</td><td>The peg is threaded into the socket until seated. Simply placing it in the opening is insufficient.</td></tr><tr><td>Timeout</td><td>120 s.</td></tr><tr><td>Reset</td><td>Unscrew and remove the peg, leave the socket empty, and restore the peg&#39;s starting pose.</td></tr></tbody></table><h2 id="covered-button" tabindex="-1">Covered button <a class="header-anchor" href="#covered-button" aria-label="Permalink to &quot;Covered button&quot;">​</a></h2><p>Task ID: <code>button</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Cover closed; button returned to its unpressed state.</td></tr><tr><td>Stage 1</td><td>Open the cover to expose the button.</td></tr><tr><td>Stage 2</td><td>Press the button until actuation.</td></tr><tr><td>Success</td><td>Both stages complete within the timeout.</td></tr><tr><td>Timeout</td><td>60 s for the complete sequence.</td></tr><tr><td>Reset</td><td>Release the button, confirm that it returns, and close the cover.</td></tr></tbody></table><p>Record <code>stage_reached = 0</code> if no stage completes, <code>1</code> if only the cover is opened, or <code>2</code> when the button is also actuated.</p><h2 id="lock-and-key" tabindex="-1">Lock and key <a class="header-anchor" href="#lock-and-key" aria-label="Permalink to &quot;Lock and key&quot;">​</a></h2><p>Task ID: <code>lock</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Lock in its locked initial state; key removed and placed in its documented starting pose.</td></tr><tr><td>Stage 1</td><td>Grasp the key.</td></tr><tr><td>Stage 2</td><td>Insert the key vertically into the lock.</td></tr><tr><td>Stage 3</td><td>Rotate the key to unlock.</td></tr><tr><td>Success</td><td>The lock is unlocked after all three stages.</td></tr><tr><td>Timeout</td><td>180 s for the complete sequence.</td></tr><tr><td>Reset</td><td>Restore the lock&#39;s initial state, remove the key, and return the key to its starting pose.</td></tr></tbody></table><p>Record the last completed stage: <code>0</code>, <code>1</code>, <code>2</code>, or <code>3</code>. Inserting the key without unlocking is stage <code>2</code>, not full success.</p><h2 id="sliding-drawer" tabindex="-1">Sliding drawer <a class="header-anchor" href="#sliding-drawer" aria-label="Permalink to &quot;Sliding drawer&quot;">​</a></h2><p>Task ID: <code>drawer</code></p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Drawer fully closed.</td></tr><tr><td>Stage 1</td><td>Grasp the handle.</td></tr><tr><td>Stage 2</td><td>Pull the drawer open.</td></tr><tr><td>Stage 3</td><td>Push the drawer closed again.</td></tr><tr><td>Success</td><td>The drawer has been opened and then closed after grasping the handle.</td></tr><tr><td>Timeout</td><td>120 s for the complete sequence.</td></tr><tr><td>Reset</td><td>Return the drawer to the fully closed position.</td></tr></tbody></table><p>Record the last completed stage: <code>0</code>, <code>1</code>, <code>2</code>, or <code>3</code>. Opening the drawer without closing it is stage <code>2</code>, not full success.</p><h2 id="shock-absorber" tabindex="-1">Shock absorber <a class="header-anchor" href="#shock-absorber" aria-label="Permalink to &quot;Shock absorber&quot;">​</a></h2><p>Task ID: <code>shock_absorber</code></p><p><strong>The task is to pick up the loose pin and insert it fully into the shock absorber&#39;s hole.</strong> The complete sequence has three stages and a single 180 s timeout.</p><table tabindex="0"><thead><tr><th>Step</th><th>Instruction</th></tr></thead><tbody><tr><td>Starting state</td><td>Pin removed from the hole and placed in its documented starting pose. Check that the attachment is seated in both occupied board cells.</td></tr><tr><td>Stage 1 — grasp</td><td>Approach and grasp the loose pin with the end-effector.</td></tr><tr><td>Stage 2 — align</td><td>Bring the pin to the hole and align its insertion axis with the hole.</td></tr><tr><td>Stage 3 — insert</td><td>Advance the aligned pin into the hole until it is fully inserted.</td></tr><tr><td>Success</td><td>All three stages are complete, with the pin fully inserted.</td></tr><tr><td>Timeout</td><td>180 s total, beginning with the first commanded task motion. Do not restart the timer between stages.</td></tr><tr><td>Reset</td><td>Remove the pin, return it to its starting pose, and check attachment seating in both board cells. Restore the end-effector&#39;s neutral pose before the next trial.</td></tr></tbody></table><p>Record the last <strong>completed</strong> stage:</p><table tabindex="0"><thead><tr><th><code>stage_reached</code></th><th>What was completed</th></tr></thead><tbody><tr><td><code>0</code></td><td>The pin was not grasped.</td></tr><tr><td><code>1</code></td><td>The pin was grasped, but alignment was not completed.</td></tr><tr><td><code>2</code></td><td>The pin was aligned with the hole, but full insertion was not completed. This includes a partially inserted pin.</td></tr><tr><td><code>3</code></td><td>The pin was fully inserted.</td></tr></tbody></table><p>For example, if the pin is aligned but only partly inserted when 180 s expires, record <code>outcome = timeout</code>, <code>stage_reached = 2</code>, and leave <code>completion_time_s</code> blank. Also record attempts, regrasps, strategy, and the primary failure cause. See <a href="/hivedocs/benchmark/logging">trial logging</a> for the field definitions.</p><p>The task definitions and timeouts follow the <a href="https://github.com/EESC-LabRoM/HiveBoard/blob/main/Documentation/PROTOCOL.md#5-per-attachment-success-criteria-and-timeouts" target="_blank" rel="noreferrer">source protocol</a>; reset instructions follow the Evaluation Runner. The protocol does not specify a numeric insertion depth, holding duration, or loose-part pose. Document the physical setup rather than introducing a different threshold for each trial.</p>',54)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
